import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.D9E58p8B.js";const g=JSON.parse('{"title":"Delegating to a sub-agent","description":"","frontmatter":{"title":"Delegating to a sub-agent"},"headers":[],"relativePath":"en/agent/deleguer.md","filePath":"en/agent/deleguer.md"}'),r={name:"en/agent/deleguer.md"};function i(s,e,h,l,u,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="delegating-to-a-sub-agent" tabindex="-1">Delegating to a sub-agent <a class="header-anchor" href="#delegating-to-a-sub-agent" aria-label="Permalink to &quot;Delegating to a sub-agent&quot;">​</a></h1><p>A sequence of actions on an interface (look, act, re-read, start over) quickly fills an agent&#39;s context with captures. It is better to hand it to a sub-agent, which returns only the result.</p><h2 id="what-you-ask" tabindex="-1">What you ask <a class="header-anchor" href="#what-you-ask" aria-label="Permalink to &quot;What you ask&quot;">​</a></h2><blockquote><p>&quot;Read the version number shown in the application&#39;s About window.&quot;</p></blockquote><h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><ol><li>It calls <a href="/Daimon/en/reference/vue.html#vue-pilot-brief"><code>vue_pilot_brief</code></a> with the objective. The tool uses no AI: it returns a <strong>go/no-go gate</strong> and a <strong>ready-to-paste prompt</strong> for a sub-agent.</li><li>If the gate is ready, it launches the sub-agent with this prompt. The captures stay inside the sub-agent; only the extracted text comes back up.</li><li>If the gate is not ready, it <strong>calibrates first</strong> with <a href="/Daimon/en/reference/vue.html#vue-calibrate"><code>vue_calibrate</code></a>, which freezes the screen topology under a name, rather than driving blind.</li></ol><p>Two tools complement the brief:</p><ul><li><a href="/Daimon/en/reference/vue.html#vue-profile"><code>vue_profile</code></a> says whether the current screen topology matches a known profile;</li><li><a href="/Daimon/en/reference/vue.html#vue-profile-brief"><code>vue_profile_brief</code></a> produces a sub-agent&#39;s starter: the profile&#39;s matching gate and addressable screen indices.</li></ul><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>The task&#39;s result, without the pile of intermediate captures.</p><h2 id="what-does-not-change" tabindex="-1">What does not change <a class="header-anchor" href="#what-does-not-change" aria-label="Permalink to &quot;What does not change&quot;">​</a></h2><p>The sub-agent works under <strong>the same ceiling</strong> as the main agent: it cannot do more. Exclusions, censoring and the audit log apply to it like to any client.</p><p>Next: <a href="/Daimon/en/agent/diagnostiquer.html">When it doesn&#39;t work</a>.</p>',13)])])}const p=t(r,[["render",i]]);export{g as __pageData,p as default};
